diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..0005520 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,33 @@ export interface Record {
   warns: readonly string[];
 }

+const semanticKey = (entry: string): string => {
+  const words = entry
+    .toLowerCase()
+    .replace(/[^\w\s]/g, ' ')
+    .split(/\s+/)
+    .filter(w => w.length > 0);
+
+  const keyTerms = words.filter(w => w.length > 3 && !['that', 'have', 'from'].includes(w));
+  return keyTerms.sort().join('|');
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seen = new Map<string, string>();
+
+  const addUnique = (prefix: string, entry: string) => {
+    const key = semanticKey(entry);
+    if (!seen.has(key)) {
+      lines.push(`- ${prefix}: ${entry}`);
+      seen.set(key, entry);
+    }
+  };
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) addUnique('ruled out', entry);
+    for (const limit of record.limits) addUnique('limit', entry);
+    for (const warn of record.warns) addUnique('warn', entry);
   }
   return lines.join("\n");
 };
